const MAPS=[
{name:'Scholar Springs',tag:'A FRESH ADVENTURE',floor:'#6ba66b',light:'#93c981',path:'#bbbf83',edge:'#355f55',stone:'#8b91a0',top:'#bac8c5',bush:'#35885d',leaf:'#66b875',accent:'#9ff5e5',water:'#408caa'},
{name:'Ember Canyon',tag:'LET YOUR CURIOSITY SHINE',floor:'#c38c65',light:'#e8b580',path:'#ebc591',edge:'#755555',stone:'#ad7d70',top:'#e0b59b',bush:'#588259',leaf:'#91ae69',accent:'#ffdf86',water:'#548f9c'},
{name:'Moonlight Circuit',tag:'BRIGHT MINDS, BIG IDEAS',floor:'#576789',light:'#7d8fad',path:'#909ab0',edge:'#303c63',stone:'#6e6f9b',top:'#acafd2',bush:'#52699e',leaf:'#8899d2',accent:'#b9f5ff',water:'#4e77a2'}
];
function prepareArena(g){g.map=MAPS[g.subject==='mixed'?Math.floor(Math.random()*3):['biology','english','health'].includes(g.subject)?0:['maths','chemistry','history','geography'].includes(g.subject)?1:2];g.walls=[{x:g.w*.22,y:g.h*.29,w:g.w*.15,h:42},{x:g.w*.63,y:g.h*.29,w:g.w*.15,h:42},{x:g.w*.22,y:g.h*.69,w:g.w*.15,h:42},{x:g.w*.63,y:g.h*.69,w:g.w*.15,h:42}];g.field=paintField(g);g.pickups=[];g.enemyShots=[];g.floaters=[];g.elapsed=0;g.waveFlash=2.3;g.shake=0;g.navClock=0;g.nav=null;g.zaps=0;$('#map-name').textContent=g.map.name;$('#arena-subtitle').textContent=(g.subject==='mixed'?'All-rounder mix':SUBJECTS.find(s=>s.id===g.subject).name)+' · '+g.map.name+' · Solo adventure'}
function roundRect(c,x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.stroke()}}
function ellipse(c,x,y,rx,ry,fill){c.fillStyle=fill;c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill()}
function paintField(g){const canvas=document.createElement('canvas');canvas.width=g.w;canvas.height=g.h;const c=canvas.getContext('2d'),w=g.w,h=g.h,m=g.map;let seed=917;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};const gradient=c.createLinearGradient(0,0,w,h);gradient.addColorStop(0,m.light);gradient.addColorStop(1,m.floor);c.fillStyle=m.edge;c.fillRect(0,0,w,h);roundRect(c,18,20,w-36,h-40,35,gradient);c.strokeStyle='#ffffff11';c.lineWidth=3;
// Soft paths and worn grass make a readable playing surface.
c.lineCap='round';c.lineJoin='round';for(const [points,width] of [[[[w*.1,h*.5],[w*.5,h*.52],[w*.9,h*.5]],115],[[[w*.5,75],[w*.5,h*.5],[w*.5,h-75]],115]]){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.strokeStyle=m.path+'83';c.lineWidth=width;c.stroke();c.strokeStyle=m.path+'44';c.lineWidth=width+25;c.stroke()}
for(let i=0;i<480;i++){const x=35+rand()*(w-70),y=35+rand()*(h-70);c.fillStyle=i%3?'#ffffff0c':'#263c3a0e';c.beginPath();c.ellipse(x,y,1+rand()*4,1+rand()*2,rand()*3,0,7);c.fill()}
// Corner pools, rippled water and stone banks.
for(const [x,y,flip]of [[w*.11,h*.14,1],[w*.88,h*.84,-1]]){c.save();c.translate(x,y);c.rotate(flip*.3);ellipse(c,4,8,72,43,'#253b4c33');ellipse(c,0,0,69,40,m.top);ellipse(c,0,-3,59,31,m.water);ellipse(c,-8,-8,41,20,'#b7f3ec22');for(let i=0;i<3;i++){c.strokeStyle='#c8f6f544';c.lineWidth=2;c.beginPath();c.ellipse(-15+i*15,-9+i*9,15,4,0,0,Math.PI);c.stroke()}c.restore()}
// Sculpted perimeter blocks and open entrance gates.
for(let x=30;x<w-30;x+=64){if(Math.abs(x-w/2)<90)continue;stone(c,x,18,58,23,m);stone(c,x,h-40,58,23,m)}for(let y=70;y<h-65;y+=64){if(Math.abs(y-h/2)<76)continue;stone(c,16,y,29,56,m);stone(c,w-47,y,29,56,m)}
for(const [x,y]of [[w*.11,h*.31],[w*.88,h*.32],[w*.13,h*.69],[w*.87,h*.62],[w*.33,h*.14],[w*.66,h*.85]]){bush(c,x,y,65,42,m,rand)}
for(const [x,y]of [[w*.095,h*.65],[w*.9,h*.45],[w*.81,h*.13],[w*.19,h*.87]]){stone(c,x,y,42,29,m);stone(c,x+29,y+18,29,25,m)}
// A low engraved courtyard is walkable; raised walls provide actual cover.
ellipse(c,w/2,h/2+8,118,94,'#233c3b21');ellipse(c,w/2,h/2,114,92,m.stone);ellipse(c,w/2,h/2-6,108,85,m.top);ellipse(c,w/2,h/2-6,91,71,m.path);c.strokeStyle='#ffffff55';c.lineWidth=2;c.beginPath();c.ellipse(w/2,h/2-6,80,62,0,0,7);c.stroke();c.fillStyle=m.edge+'88';c.textAlign='center';c.font='800 16px sans-serif';c.fillText('QUEST',w/2,h/2-15);c.font='900 28px sans-serif';c.fillText('✦',w/2,h/2+21);for(const wall of g.walls){stone(c,wall.x,wall.y,wall.w,wall.h,m);c.fillStyle=m.edge+'66';c.font='bold 17px sans-serif';c.fillText('◆',wall.x+wall.w/2,wall.y+wall.h/2-3)}
for(const [x,y]of [[w*.5,58],[w*.5,h-58],[64,h*.5],[w-64,h*.5]]){ellipse(c,x,y+5,25,14,'#263d4933');ellipse(c,x,y,22,12,m.edge);ellipse(c,x,y-2,15,7,m.accent+'77')}
return canvas}
function stone(c,x,y,w,h,m){roundRect(c,x+5,y+9,w,h,8,'#26344533');roundRect(c,x,y+5,w,h,7,m.edge);roundRect(c,x,y-7,w,h,7,m.stone);roundRect(c,x+3,y-9,w-6,h-5,6,m.top);c.lineWidth=2;c.strokeStyle='#ffffff33';c.beginPath();c.moveTo(x+9,y-4);c.lineTo(x+w-10,y-4);c.stroke();c.strokeStyle=m.edge+'55';c.beginPath();c.moveTo(x+w*.63,y-7);c.lineTo(x+w*.59,y+3);c.lineTo(x+w*.67,y+9);c.stroke()}
function bush(c,x,y,w,h,m,rand){ellipse(c,x+7,y+14,w*.65,h*.55,'#213b3933');for(let i=0;i<18;i++){const a=i*2.4,r=Math.sqrt(i/18),bx=x+Math.cos(a)*w*.55*r,by=y+Math.sin(a)*h*.5*r;ellipse(c,bx,by+3,15,19,m.bush);ellipse(c,bx-2,by-4,12,15,i%3?m.leaf:m.bush);c.strokeStyle='#ffffff17';c.lineWidth=2;c.beginPath();c.moveTo(bx,by-12);c.lineTo(bx-3,by-1);c.stroke()}}
function blocked(g,x,y,r=0){return x<28+r||x>g.w-28-r||y<30+r||y>g.h-30-r||g.walls.some(b=>x>b.x-r&&x<b.x+b.w+r&&y>b.y-r&&y<b.y+b.h+r)}
function moveBody(g,e,dx,dy,r=23){if(!blocked(g,e.x+dx,e.y,r))e.x+=dx;if(!blocked(g,e.x,e.y+dy,r))e.y+=dy}
function lineClear(g,x,y,tx,ty,r=0){const d=Math.hypot(tx-x,ty-y),n=Math.max(1,Math.ceil(d/12));for(let i=1;i<=n;i++)if(blocked(g,x+(tx-x)*i/n,y+(ty-y)*i/n,r))return false;return true}
function navigation(g){const step=40,cols=Math.ceil(g.w/step),rows=Math.ceil(g.h/step),dist=new Int16Array(cols*rows).fill(-1),goalX=Math.min(cols-1,Math.floor(g.x/step)),goalY=Math.min(rows-1,Math.floor(g.y/step)),q=[[goalX,goalY]];dist[goalY*cols+goalX]=0;for(let p=0;p<q.length;p++){const [x,y]=q[p];for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,k=ny*cols+nx;if(nx<0||nx>=cols||ny<0||ny>=rows||dist[k]>=0||blocked(g,nx*step+step/2,ny*step+step/2,24))continue;dist[k]=dist[y*cols+x]+1;q.push([nx,ny])}}g.nav={dist,step,cols,rows}}
function steerBot(g,e,dt){let tx=g.x,ty=g.y;if(!lineClear(g,e.x,e.y,tx,ty,24)&&g.nav){const n=g.nav,x=Math.floor(e.x/n.step),y=Math.floor(e.y/n.step);let best=Infinity;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=n.cols||ny>=n.rows)continue;const v=n.dist[ny*n.cols+nx],cx=nx*n.step+20,cy=ny*n.step+20;if(v>=0&&v<best&&lineClear(g,e.x,e.y,cx,cy,23)){best=v;tx=cx;ty=cy}}}const d=Math.hypot(tx-e.x,ty-e.y)||1;moveBody(g,e,(tx-e.x)/d*e.speed*dt,(ty-e.y)/d*e.speed*dt,23)}
function spawnWave(){spawnChallengeWave()}
function shoot(){const g=game;if(!g||g.paused||g.cooldown>0||g.ammo<=0)return;const targets=g.enemies.filter(e=>e.hp>0&&e.spawnShield<=0&&Math.hypot(e.x-g.x,e.y-g.y)<(g.mode.id==='scout'?1200:460)&&lineClear(g,g.x,g.y,e.x,e.y,6)).sort((a,b)=>Math.hypot(a.x-g.x,a.y-g.y)-Math.hypot(b.x-g.x,b.y-g.y));const e=targets[0];if(!e)return;const angle=Math.atan2(e.y-g.y,e.x-g.x);g.bullets.push({x:g.x,y:g.y,dx:Math.cos(angle)*700,dy:Math.sin(angle)*700,life:1.6});g.ammo--;GameAudio.effect('shoot');g.cooldown=g.hero.shotDelay;g.zaps=.12}
function superAttack(){const g=game;if(!g||g.paused)return;if(g.charge<3){toast('Answer 3 questions correctly to charge your super.');return}g.charge=0;GameAudio.effect('super');g.enemies.filter(e=>e.spawnShield<=0&&Math.hypot(e.x-g.x,e.y-g.y)<=g.mode.superRadius).forEach(e=>{e.hp-=g.hero.superDamage;e.flash=.2;burst(e.x,e.y,'#d5fa59',25)});burst(g.x,g.y,'#b59aff',45);g.superRing=.65;g.shake=.15;}
function damagePlayer(g){if(g.invincible>0)return;GameAudio.effect('hurt');g.hp-=g.monsterDamage;g.invincible=g.mode.id==='scout'?1.6:1.05;g.lastHurt=g.elapsed;g.shake=.2;burst(g.x,g.y,'#ff9caa');g.floaters.push({x:g.x,y:g.y-55,text:'−'+g.monsterDamage+' ♥',colour:'#ffb7b7',life:1})}
function updateArena(dt){const g=game;g.time-=dt;g.elapsed+=dt;g.sinceQ+=dt;g.cooldown=Math.max(0,g.cooldown-dt);g.invincible=Math.max(0,g.invincible-dt);g.waveFlash=Math.max(0,g.waveFlash-dt);g.shake=Math.max(0,g.shake-dt);g.zaps=Math.max(0,g.zaps-dt);g.superRing=Math.max(0,(g.superRing||0)-dt);g.navClock-=dt;if(g.navClock<=0){navigation(g);g.navClock=.35}let dx=+!!(keys.ArrowRight||keys.d)-+!!(keys.ArrowLeft||keys.a),dy=+!!(keys.ArrowDown||keys.s)-+!!(keys.ArrowUp||keys.w);if(stick.pointerId!==null){dx=stick.x;dy=stick.y}const mag=Math.max(1,Math.hypot(dx,dy));if(Math.hypot(dx,dy)>.05)g.facing={x:dx/mag,y:dy/mag};if(g.dashRemaining>0){dx=g.facing.x;dy=g.facing.y;moveBody(g,g,dx*700*dt,dy*700*dt,26)}else moveBody(g,g,dx/mag*g.speed*dt,dy/mag*g.speed*dt,26);updateChallenge(g,dt);g.rechargeCooldown=Math.max(0,g.rechargeCooldown-dt);g.energyClock+=dt;if(g.energyClock>=1.8){g.energyClock-=1.8;g.ammo=Math.min(g.maxAmmo,g.ammo+1)}g.moving=!!(dx||dy);if(keys[' ']||firePointerId!==null)shoot();runEnemyAI(g,dt);for(const b of g.bullets){b.x+=b.dx*dt;b.y+=b.dy*dt;b.life-=dt;if(blocked(g,b.x,b.y,4)){b.life=0;burst(b.x,b.y,g.map.accent,3);continue}const e=g.enemies.find(e=>e.hp>0&&e.spawnShield<=0&&Math.hypot(e.x-b.x,e.y-b.y)<e.r+7);if(e){e.hp-=b.damage||g.attackPower;GameAudio.effect('hit');e.flash=.15;if(!advancePiercingShot(b,e))b.life=0;burst(e.x,e.y,'#f8cf6c',9);g.floaters.push({x:e.x,y:e.y-33,text:'−'+g.attackPower,colour:'#ffed9b',life:.6})}}g.bullets=g.bullets.filter(b=>b.life>0);for(const b of g.enemyShots){b.x+=b.dx*dt;b.y+=b.dy*dt;b.life-=dt;if(blocked(g,b.x,b.y,7)){b.life=0;continue}if(Math.hypot(b.x-g.x,b.y-g.y)<30){damagePlayer(g);b.life=0}}g.enemyShots=g.enemyShots.filter(b=>b.life>0);g.enemies=g.enemies.filter(e=>{if(e.hp<=0){g.kills++;g.charge=Math.min(3,g.charge+.5);GameAudio.effect('defeat');burst(e.x,e.y,'#ffe4a0',18);g.pickups.push({x:e.x,y:e.y,life:18});return false}return true});g.pickups=g.pickups.filter(p=>{p.life-=dt;const d=Math.hypot(p.x-g.x,p.y-g.y);if(d<80){p.x+=(g.x-p.x)*dt*6;p.y+=(g.y-p.y)*dt*6}if(d<30){GameAudio.effect('pickup');g.ammo=Math.min(g.maxAmmo,g.ammo+1);g.floaters.push({x:g.x,y:g.y-55,text:'+1 ENERGY',colour:'#b8f7df',life:1});return false}return p.life>0});g.particles.forEach(p=>{p.x+=p.dx*dt;p.y+=p.dy*dt;p.life-=dt});g.particles=g.particles.filter(p=>p.life>0);g.floaters.forEach(p=>{p.y-=dt*35;p.life-=dt});g.floaters=g.floaters.filter(p=>p.life>0);if(g.hp<=0||g.time<=0){finishArena(false);return false}if(!g.enemies.length){if(g.wave>=g.totalWaves){finishArena(true);return false}spawnWave()}return true}
function drawPetPlayer(c,g){if(!drawBreedAvatar(c,g))drawSimplePetPlayer(c,g)}
function drawSimplePetPlayer(c,g){const h=g.hero,bob=g.moving?Math.sin(g.elapsed*15)*2:Math.sin(g.elapsed*3);c.save();c.translate(g.x,g.y);ellipse(c,0,26,33,12,'#203b3f55');c.strokeStyle='#d5fa5980';c.lineWidth=3;c.beginPath();c.ellipse(0,25,36,16,0,0,7);c.stroke();if(g.invincible>0){c.strokeStyle='#bbf6ee80';c.beginPath();c.arc(0,0,41,0,7);c.stroke()}c.translate(0,bob);roundRect(c,-21,4,42,28,10,'#3f4968','#303348');c.fillStyle=PET_RANKS[h.rank-1].colour;c.beginPath();c.moveTo(-21,3);c.lineTo(0,23);c.lineTo(21,3);c.fill();if(h.species==='cat'||h.ears==='pointed'||h.ears==='tufted'){c.fillStyle=h.colour;c.strokeStyle='#343447';c.lineWidth=3;c.beginPath();c.moveTo(-23,-10);c.lineTo(-26,-45);c.lineTo(-6,-27);c.lineTo(9,-27);c.lineTo(26,-45);c.lineTo(23,-5);c.fill();c.stroke()}else{ellipse(c,-25,-11,11,24,'#795d57');ellipse(c,25,-11,11,24,'#795d57')}ellipse(c,0,-9,27,25,'#343447');ellipse(c,0,-12,25,24,h.colour);if(h.rank>=9&&h.species==='dog')ellipse(c,0,-16,10,22,'#efe5cf');ellipse(c,0,1,14,11,'#f1dcc3');ellipse(c,-10,-15,3,5,'#292b43');ellipse(c,10,-15,3,5,'#292b43');ellipse(c,0,-3,5,3,'#433747');if(h.rank>=3){c.lineWidth=2;c.strokeStyle='#30354b';c.strokeRect(-17,-23,14,14);c.strokeRect(3,-23,14,14);c.beginPath();c.moveTo(-3,-16);c.lineTo(3,-16);c.stroke()}if(h.species==='cat'){c.strokeStyle='#f2dfcc';c.lineWidth=2;c.beginPath();c.moveTo(-13,0);c.lineTo(-31,-3);c.moveTo(13,0);c.lineTo(31,-3);c.stroke()}if(h.rank>=9){c.fillStyle='#ffe08c';c.beginPath();c.moveTo(-18,-32);c.lineTo(-22,-48);c.lineTo(-8,-42);c.lineTo(0,-54);c.lineTo(8,-42);c.lineTo(22,-48);c.lineTo(18,-32);c.fill()}roundRect(c,20,2,16,23,5,g.zaps?'#eaffc4':'#a9dbe5','#3a5272');c.fillStyle='#f6f6ff';c.textAlign='center';c.font='800 12px sans-serif';c.shadowColor='#1c274c';c.shadowBlur=4;c.fillText(h.name,0,-65);c.shadowBlur=0;c.restore()}
function drawBot(c,e,g){if(e.type==='boss'){renderBoss(c,e,g);return}c.save();if(e.spawnShield>0)c.globalAlpha=.45;c.translate(e.x,e.y+Math.sin(g.elapsed*4+e.x)*1.4);const fill=e.flash?'#fff0c0':e.type==='tank'?'#ba91d3':e.type==='blaster'?'#e99186':'#efbd70';ellipse(c,1,26,28,11,'#263b4755');ellipse(c,0,25,32,14,'#ffb1ad33');c.strokeStyle='#533e57';c.lineWidth=4;roundRect(c,-24,-24,48,47,13,fill,'#533e57');roundRect(c,-17,-12,34,18,6,'#3c3954');c.fillStyle=e.type==='blaster'?'#f7b7bf':'#f9e5a1';c.fillRect(-12,-7,8,7);c.fillRect(4,-7,8,7);c.strokeStyle='#ded3e6';c.beginPath();c.moveTo(0,-24);c.lineTo(0,-36);c.stroke();ellipse(c,0,-37,5,5,fill);if((e.type==='blaster'&&e.fire<.5)||(e.type==='scout'&&e.dashClock<.45)){c.strokeStyle='#ffba99';c.lineWidth=3;c.beginPath();c.arc(0,0,32+e.fire*8,0,7);c.stroke()}roundRect(c,-25,-52,50,7,3,'#313e5266');roundRect(c,-24,-51,48*Math.max(0,e.hp)/e.maxHp,5,2,'#ffce9a');if(e.type==='tank'){roundRect(c,-31,-4,9,20,4,'#7e689e');roundRect(c,22,-4,9,20,4,'#7e689e')}c.restore()}
function renderArena(g){const c=g.ctx;c.clearRect(0,0,g.w,g.h);c.save();if(g.shake>0)c.translate(Math.sin(g.elapsed*90)*g.shake*12,Math.cos(g.elapsed*80)*g.shake*12);c.drawImage(g.field,0,0);renderHazards(c,g);for(const p of g.pickups){const bob=Math.sin(g.elapsed*5+p.x)*4;ellipse(c,p.x,p.y+11,14,6,'#25474344');c.save();c.translate(p.x,p.y+bob);c.fillStyle='#a7f3e0';c.strokeStyle='#e3fff6';c.lineWidth=2;c.beginPath();c.moveTo(0,-14);c.lineTo(10,0);c.lineTo(0,14);c.lineTo(-10,0);c.closePath();c.fill();c.stroke();c.restore()}const target=g.enemies.find(e=>e.spawnShield<=0&&Math.hypot(e.x-g.x,e.y-g.y)<(g.mode.id==='scout'?1200:460)&&lineClear(g,g.x,g.y,e.x,e.y));if(target){c.strokeStyle='#e9ffbf55';c.lineWidth=2;c.beginPath();c.arc(target.x,target.y,34,g.elapsed*2,g.elapsed*2+Math.PI*1.4);c.stroke()}for(const e of [...g.enemies].sort((a,b)=>a.y-b.y))drawBot(c,e,g);drawPetPlayer(c,g);for(const b of g.bullets){c.strokeStyle=(b.colour||'#f1ffbf')+'88';c.lineWidth=7;c.lineCap='round';c.beginPath();c.moveTo(b.x-b.dx*.025,b.y-b.dy*.025);c.lineTo(b.x,b.y);c.stroke();ellipse(c,b.x,b.y,7,7,b.colour||'#f4ffcc')}for(const b of g.enemyShots){ellipse(c,b.x,b.y,12,12,'#f495a14d');ellipse(c,b.x,b.y,7,7,'#ffc5b9');ellipse(c,b.x-2,b.y-2,3,3,'#fff0d3')}if(g.superRing>0){c.strokeStyle='#e1ff9988';c.lineWidth=g.superRing*14;c.beginPath();c.arc(g.x,g.y,(.65-g.superRing)/.65*g.mode.superRadius+20,0,7);c.stroke()}for(const p of g.particles){c.globalAlpha=Math.max(0,p.life/.6);c.fillStyle=p.colour;c.fillRect(p.x,p.y,5,5)}c.globalAlpha=1;for(const p of g.floaters){c.globalAlpha=Math.min(1,p.life*2);c.textAlign='center';c.font='900 17px sans-serif';c.strokeStyle='#39354f';c.lineWidth=4;c.strokeText(p.text,p.x,p.y);c.fillStyle=p.colour;c.fillText(p.text,p.x,p.y)}c.globalAlpha=1;if(g.waveFlash>0&&!g.boss){c.globalAlpha=Math.min(1,g.waveFlash);roundRect(c,g.w/2-128,84,256,66,16,'#252947db','#d2e5de66');c.fillStyle='#edffd5';c.font='900 26px sans-serif';c.textAlign='center';c.fillText('WAVE '+g.wave+' / '+g.totalWaves,g.w/2,114);c.fillStyle='#c6d7da';c.font='11px sans-serif';c.fillText(g.wave===1?'DODGE · ZAP · LEARN':'NEW CHALLENGERS INCOMING',g.w/2,135);c.globalAlpha=1}c.restore();if(!movementHUDDue(g))return;$('#hp').textContent='♥ '+Math.max(0,g.hp)+' / '+g.maxHp;$('#wave').textContent=`WAVE ${g.wave}/${g.totalWaves} · ${g.kills}/${g.totalBots}`;$('#timer').textContent=Math.floor(Math.ceil(Math.max(0,g.time))/60)+':'+String(Math.ceil(Math.max(0,g.time))%60).padStart(2,'0');$('#ammo').textContent=g.ammo;$('#charge').textContent=g.charge===3?'READY!':Math.round(g.charge/3*100)+'%';document.querySelector('.super-button')?.classList.toggle('ready',g.charge===3);updateProHUD(g)}
